def apply(name, v, x, y, n=8):
    s = 0
    for c, mon in ROWS[name]:
        t = c
        for slot, coord in mon:
            t *= (v, x, y)[slot][coord]
        s += t
    return s % n if n else s


def sigFiveRead(v, x, y, n=8):
    """The class-five sigma-reading functional: the amount by which the top row x16 of the
    core word moves when the sigma slot is dressed by a nu-trivial v."""
    return apply('o', v, x, y, n)

